const filter = process.argv[2];
let proved = 0;
let ran = 0;
for (const m of MUTATIONS) {
  if (filter && !m.name.includes(filter)) continue;
  ran++;
  const original = readFileSync(m.file, 'utf8');
  const before = sha(original);
  const crlf = original.includes('\r\n');
  const text = crlf ? original.replace(/\r\n/g, '\n') : original;
  if (text.split(m.from).length !== 2) { console.log(`NOT PROVED ${m.name}: the anchor is not exactly once in ${m.file}`); continue; }
  const mutated = text.replace(m.from, () => m.to);
  let status;
  try {
    safeWrite(m.file, crlf ? mutated.replace(/\n/g, '\r\n') : mutated);
    status = spawnSync('npx', ['vitest', 'run', m.test], { encoding: 'utf8', shell: true }).status;
  } finally {
    safeWrite(m.file, original);
  }
  const after = sha(readFileSync(m.file, 'utf8'));
  const restored = before === after;
  const equivalent = !!m.equivalent && status === 0 && restored;
  const ok = (status !== 0 && restored) || equivalent;
  if (ok) proved++;
  console.log(`${equivalent ? 'EQUIVALENT' : ok ? 'PROVED    ' : 'NOT PROVED'} ${m.name}: with it broken the tests ${status !== 0 ? 'fail' : 'still pass'}${equivalent ? ` (${m.equivalent})` : ''}; file restored: ${restored}`);
}
console.log(`\n${proved} of ${ran} proved.`);
process.exitCode = proved === ran ? 0 : 1;
